#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int d, q;
    cin >> d >> q;
    vector<ll> window(d), limit(d);
    for (int i = 0; i < d; i++) { string name; cin >> name >> window[i] >> limit[i]; }
    // Per dimension: value -> id; per id the allowed timestamps, with a head index as the deque front.
    vector<unordered_map<string, int>> ids(d);
    vector<vector<vector<ll>>> times(d);
    vector<vector<size_t>> head(d);
    vector<int> cur(d);
    string out;
    for (int r = 0; r < q; r++) {
        ll now;
        cin >> now;
        for (int i = 0; i < d; i++) {
            string key;
            cin >> key;
            auto [it, fresh] = ids[i].try_emplace(key, (int)times[i].size());
            if (fresh) { times[i].emplace_back(); head[i].push_back(0); }
            int id = cur[i] = it->second;
            auto& t = times[i][id];
            size_t& h = head[i][id];
            // Window is [now - window, now): drop timestamps <= now - window.
            while (h < t.size() && t[h] <= now - window[i]) h++;
        }
        bool ok = true;
        for (int i = 0; i < d && ok; i++) ok = (ll)(times[i][cur[i]].size() - head[i][cur[i]]) < limit[i];
        if (r) out += ' ';
        out += ok ? "ALLOW" : "REJECT";
        if (ok) for (int i = 0; i < d; i++) times[i][cur[i]].push_back(now);
    }
    out += '\n';
    cout << out;
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static String next() {
        while (buf[bp] <= ' ') bp++;
        int s = bp;
        while (bp < buf.length && buf[bp] > ' ') bp++;
        return new String(buf, s, bp - s);
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int d = Integer.parseInt(next()), q = Integer.parseInt(next());
        long[] window = new long[d], limit = new long[d];
        for (int i = 0; i < d; i++) { next(); window[i] = Long.parseLong(next()); limit[i] = Long.parseLong(next()); }
        // Per dimension: value -> id; per id a growable array of allowed timestamps with a head index as the deque front.
        List<HashMap<String, Integer>> ids = new ArrayList<>();
        List<List<long[]>> times = new ArrayList<>();
        List<int[]> heads = new ArrayList<>(), sizes = new ArrayList<>();
        for (int i = 0; i < d; i++) {
            ids.add(new HashMap<>());
            times.add(new ArrayList<>());
            heads.add(new int[16]);
            sizes.add(new int[16]);
        }
        int[] cur = new int[d];
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < q; r++) {
            long now = Long.parseLong(next());
            for (int i = 0; i < d; i++) {
                String key = next();
                Integer id = ids.get(i).get(key);
                if (id == null) {
                    id = times.get(i).size();
                    ids.get(i).put(key, id);
                    times.get(i).add(new long[2]);
                    if (id >= heads.get(i).length) {
                        heads.set(i, Arrays.copyOf(heads.get(i), id * 2));
                        sizes.set(i, Arrays.copyOf(sizes.get(i), id * 2));
                    }
                }
                cur[i] = id;
                long[] t = times.get(i).get(id);
                int[] h = heads.get(i), sz = sizes.get(i);
                // Window is [now - window, now): drop timestamps <= now - window.
                while (h[id] < sz[id] && t[h[id]] <= now - window[i]) h[id]++;
            }
            boolean ok = true;
            for (int i = 0; i < d && ok; i++) ok = sizes.get(i)[cur[i]] - heads.get(i)[cur[i]] < limit[i];
            if (r > 0) sb.append(' ');
            sb.append(ok ? "ALLOW" : "REJECT");
            if (ok)
                for (int i = 0; i < d; i++) {
                    int id = cur[i], s = sizes.get(i)[id];
                    long[] t = times.get(i).get(id);
                    if (s == t.length) times.get(i).set(id, t = Arrays.copyOf(t, s * 2));
                    t[s] = now;
                    sizes.get(i)[id] = s + 1;
                }
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	num := func() int64 { v, _ := strconv.ParseInt(next(), 10, 64); return v }
	d, q := int(num()), int(num())
	window, limit := make([]int64, d), make([]int64, d)
	for i := 0; i < d; i++ {
		next()
		window[i], limit[i] = num(), num()
	}
	// Per dimension: value -> id; per id the allowed timestamps, with a head index as the deque front.
	ids := make([]map[string]int, d)
	times := make([][][]int64, d)
	head := make([][]int, d)
	for i := range ids {
		ids[i] = map[string]int{}
	}
	cur := make([]int, d)
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for r := 0; r < q; r++ {
		now := num()
		for i := 0; i < d; i++ {
			key := next()
			id, ok := ids[i][key]
			if !ok {
				id = len(times[i])
				ids[i][key] = id
				times[i] = append(times[i], nil)
				head[i] = append(head[i], 0)
			}
			cur[i] = id
			t := times[i][id]
			// Window is [now - window, now): drop timestamps <= now - window.
			for head[i][id] < len(t) && t[head[i][id]] <= now-window[i] {
				head[i][id]++
			}
		}
		ok := true
		for i := 0; i < d && ok; i++ {
			ok = int64(len(times[i][cur[i]])-head[i][cur[i]]) < limit[i]
		}
		if r > 0 {
			w.WriteByte(' ')
		}
		if ok {
			w.WriteString("ALLOW")
			for i := 0; i < d; i++ {
				times[i][cur[i]] = append(times[i][cur[i]], now)
			}
		} else {
			w.WriteString("REJECT")
		}
	}
	w.WriteByte('\n')
}
